// Single-bit edge-triggered registers capture the 1->0 transition of the
// input, register the 1, and go back to looking for the next 1->0
// transition. This forms a kind of delay, with the delay time roughly
// proportional to the number of cycles between the 1->0 transitions.
module TopModule(
    input  clk,
    input  reset,
    input  [31:0] in,
    output [31:0] out
);
    reg [31:0] r;
    reg [31:0] r2;
    wire [31:0] q;
    wire [31:0] q2;
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : bit_reg
            always @(posedge clk) begin
                if (reset) begin
                    r[i] <= 1'b0;
                    r2[i] <= 1'b0;
                end else begin
                    r[i] <= in[i] & ~r2[i];
                    r2[i] <= r[i];
                end
            end
            assign q[i] = r[i] & ~r2[i];
            assign q2[i] = r2[i] & ~(r[i] & r2[i]);
        end
    endgenerate
    assign out = q | q2;
endmodule

